import {createLocalServer} from '../../src/interfaces/http/create-local-server.js';import {createApplicationIntelligence} from '../../src/application/application-intelligence.js';import {createApplicationIntelligenceStore} from '../../src/infrastructure/applications/sqlite-application-intelligence.js';import {createOutreachRepository} from '../../src/infrastructure/outreach/sqlite-outreach-repository.js';import {vacancyIdentity} from '../../src/application/vacancy-identity.js';import {createHash} from 'node:crypto';import path from 'node:path';
const root=process.argv[2],form={jobTitle:'Delivery Lead',organisationName:'Example',organisationUrl:'https://example.test',jobLocation:'London',jobAdvertLink:'https://www.linkedin.com/jobs/view/123456/',jobReference:'R-1',jobDescriptionText:'Delivery leadership governance budgeting stakeholders benefits strategic outcomes.'},cv={role_code:'DM',role_name:'Delivery Manager',local_path:'synthetic-evidence.txt',tags:['delivery'],use_cases:[],priority:'high'},plain='Dear Hiring Manager,\n\nI delivered verified strategic outcomes.\n\nWarm regards,\nExample Candidate',prepared={recommendation:{bestCv:cv,alternativeCv:null,ats:{score:80}},rankedCvs:[{cv,ats:{score:80,matchedKeywords:['delivery'],missingKeywords:[],suggestions:[]}}],coverLetter:{subject:'Reviewed application',plainText:plain,richText:plain.replaceAll('\n','<br>')}},reviews=new Map([['fixture-review',{formData:form,prepared,selectedCvRoleCode:'DM',currentDraftPlainText:plain,currentDraftHtml:prepared.coverLetter.richText,currentDraftSubject:'Reviewed application',createdAt:Date.now()}],['previous-review',{formData:form,prepared,selectedCvRoleCode:'DM',currentDraftPlainText:plain,currentDraftSubject:'Older application',createdAt:1}]]);
const outreach=createOutreachRepository({filePath:path.join(root,'outreach.db')}),queue=outreach.addMany([{applicationKey:vacancyIdentity(form).legacyKey,contactId:'synthetic-contact',email:'old-recipient@example.test',subject:'Synthetic outreach',bodyPlainText:plain,application:{...form,selectedCvRoleCode:'DM'}}]).items[0];outreach.recordConfirmedSend({queueId:queue.id,sendingAccount:'sender@example.test',messageId:'synthetic-record-id'});
const store=createApplicationIntelligenceStore({filePath:path.join(root,'intelligence.db')}),evidence='Delivery leadership governance';const service=createApplicationIntelligence({reviews,outreach,store,inventory:{load:async()=>({cvs:[cv]})},documentExtractor:{extract:async()=>({text:evidence,sha256:createHash('sha256').update(evidence).digest('hex'),warnings:[]})}});
const server=createLocalServer({applicationReviewStore:reviews,outreachRepository:outreach,applicationIntelligence:service,prepareApplication:async()=>prepared});server.listen(0,'127.0.0.1',()=>process.stdout.write(String(server.address().port)+'\n'));server.on('close',()=>{store.close();outreach.close();});
